exercise.solution:
function summarizeCart(items) {
  const count = items.reduce((sum, item) => sum + item.quantity, 0);
  const total = Math.round(
    items.reduce((sum, item) => sum + item.price * item.quantity, 0) * 100
  ) / 100;

  const mostExpensiveItem = items.reduce((current, item) => {
    if (current === null || item.price > current.price) {
      return item;
    }
    return current;
  }, null);

  return {
    count,
    total,
    mostExpensive: mostExpensiveItem ? mostExpensiveItem.name : null
  };
}

function groupBy(items, key) {
  return items.reduce((groups, item) => {
    const groupKey = item[key];

    if (!Object.prototype.hasOwnProperty.call(groups, groupKey)) {
      groups[groupKey] = [];
    }

    groups[groupKey].push(item);
    return groups;
  }, {});
}
